/** Per-voice SuperSAW levels at a SSAW_DETUNE value (0..127). */
function ssawAmps(detune) {
  const d = Math.max(0, Math.min(127, detune));
  const xs = SSAW.detune;
  let i = 1;
  while (i < xs.length - 1 && xs[i] < d) i++;
  const t = (d - xs[i - 1]) / (xs[i] - xs[i - 1]);
  const a0 = SSAW.amp[i - 1], a1 = SSAW.amp[i];
  return a0.map((v, k) => v + (a1[k] - v) * Math.max(0, Math.min(1, t)));
}

const WT_SIZE = 2048;
/** Output gain of a voice at full tone level, calibrated against Zenology. */
const VOICE_GAIN = 0.25 * Math.pow(10, 0.44 / 20);
const wtCache = new Map();

/** One period of a captured waveform, band-limited to maxK harmonics. */
function waveTable(form, idx, maxK) {
  const key = `${form}|${idx}|${maxK}`;
  let t = wtCache.get(key);
  if (t) return t;
  const cap = WAVES.tables[form][idx];
  const K = Math.min(maxK, cap.a.length);
  t = new Float32Array(WT_SIZE + 1);
  for (let k = 1; k <= K; k++) {
    const a = cap.a[k - 1], ph = cap.p[k - 1];
    if (a < 1e-6) continue;
    const w = (TAU * k) / WT_SIZE;
    for (let j = 0; j < WT_SIZE; j++) t[j] += a * Math.cos(w * j + ph);
  }
  t[WT_SIZE] = t[0];
  wtCache.set(key, t);
  return t;
}

/** Harmonic budget for a pitch, in 1/12-octave steps so tables are shared. */
function harmonicBudget(hz, sr) {
  const k = Math.max(1, Math.floor((0.45 * sr) / Math.max(hz, 1)));
  return Math.max(1, Math.floor(Math.pow(2, Math.floor(Math.log2(k) * 12) / 12)));
}

export class VAOsc {
  constructor(sampleRate) {
    this.sr = sampleRate;
    this.phase = 0;
    this.form = "SAW";
    this.pw = 0.5;
    /** SAW and SQR play their captured tables only while PW is fixed at 64;
     *  anything moving PW needs the analytic, PW-following versions. */
    this.pwLocked = false;
    this.syncedThisSample = false;
  }

  reset(phase = 0) {
    this.phase = phase;
    if (this.form === "SSAW" && SSAW.phase) {
      this.ssawPh = Float64Array.from(SSAW.phase);
      if (this.hpS) this.hpS = [0, 0];
    }
  }

  /** SuperSAW detune (SSAW_DETUNE, 0..127, fractional under modulation). */
  setDetune(d) {
    if (d === this.ssawDetune || !SSAW.amp) return;
    this.ssawDetune = d;
    this.ssawAmp = Float64Array.from(ssawAmps(d));
    if (SSAW.hpf?.length) {
      this.ssawHpf = interp(SSAW.hpf, Math.max(0, Math.min(127, d)), false);
      this.hpS ??= [0, 0];
    }
  }

  /** Advance one sample at `hz`; returns [-1,1]. Sets syncedThisSample when
   *  the phase wrapped, which is what a sync slave listens for. */
  tick(hz) {
    const dt = hz / this.sr;
    if (this.form === "SSAW" && SSAW.cents) return this.tickSsaw(hz, dt);
    const tabled = this.form in (WAVES.tables || {})
      && (this.pwLocked || (this.form !== "SAW" && this.form !== "SQR"));
    if (!tabled) this.table = null;
    // re-pick at most every 32 samples, so audio-rate pitch modulation (XMOD)
    // does not rebuild or look up tables on every sample
    else if (!this.table || (((this.tableTick = (this.tableTick | 0) + 1) & 31) === 0
             && Math.abs(hz / this.tableHz - 1) > 0.03)) {
      // nearest captured octave, band-limited to this pitch
      const caps = WAVES.tables[this.form];
      const note = 69 + 12 * Math.log2(Math.max(hz, 1) / 440);
      let idx = 0;
      for (let i = 1; i < caps.length; i++) {
        if (Math.abs(caps[i].note - note) < Math.abs(caps[idx].note - note)) idx = i;
      }
      this.table = waveTable(this.form, idx, harmonicBudget(hz * 1.03, this.sr));
      this.tableHz = hz;
    }
    this.phase += dt;
    this.syncedThisSample = this.phase >= 1;
    if (this.syncedThisSample) this.phase -= Math.floor(this.phase);
    return this.shape(this.phase, dt);
  }

  /** SuperSAW: 14 SAW-table voices at their fixed detunes and measured levels. */
  tickSsaw(hz, dt) {
    if (!this.ssawRatio) {
      this.ssawRatio = Float64Array.from(SSAW.cents, (c) => Math.pow(2, c / 1200));
      if (!this.ssawPh) this.ssawPh = Float64Array.from(SSAW.phase);
      if (!this.ssawAmp) this.setDetune(64);
    }
    if (!this.table || (((this.tableTick = (this.tableTick | 0) + 1) & 31) === 0
        && Math.abs(hz / this.tableHz - 1) > 0.03)) {
      const caps = WAVES.tables.SAW;
      const note = 69 + 12 * Math.log2(Math.max(hz, 1) / 440);
      let idx = 0;
      for (let i = 1; i < caps.length; i++) {
        if (Math.abs(caps[i].note - note) < Math.abs(caps[idx].note - note)) idx = i;
      }
      // band-limit for the highest voice (+40 cents)
      this.table = waveTable("SAW", idx, harmonicBudget(hz * 1.03 * 1.024, this.sr));
      this.tableHz = hz;
    }
    const tab = this.table, ph = this.ssawPh, r = this.ssawRatio, amp = this.ssawAmp;
    let out = 0;
    for (let v = 0; v < ph.length; v++) {
      let p = ph[v] + dt * r[v];
      if (p >= 1) p -= 1;
      ph[v] = p;
      const x = p * WT_SIZE, i = x | 0;
      out += amp[v] * (tab[i] + (tab[i + 1] - tab[i]) * (x - i));
    }
    // Zenology's SuperSAW fundamental sits 2-4 dB below its other harmonics:
    // a 2-pole (TPT, Butterworth) highpass tracking the note, cutoff per detune
    if (this.ssawHpf) {
      const g = Math.tan(Math.PI * Math.min(hz * this.ssawHpf, this.sr * 0.45) / this.sr);
      const k = Math.SQRT2, h = 1 / (1 + g * (g + k)), s = this.hpS;
      const hp = (out - (g + k) * s[0] - s[1]) * h;
      const bp = g * hp + s[0];
      const lp = g * bp + s[1];
      s[0] = g * hp + bp;
      s[1] = g * bp + lp;
      out = hp;
    }
    // a centre phase at the note's own pitch, for sync and the structure code
    this.phase += dt;
    this.syncedThisSample = this.phase >= 1;
    if (this.syncedThisSample) this.phase -= Math.floor(this.phase);
    return out;
  }

  /** Roland applies PULSE WIDTH to VA waveforms other than SQR - the manual
   *  says so explicitly, and factory preset "Kaihou Keys" runs PW=127 on SAW
   *  partials. SAW has its own measured morph (sawMorph); for the other forms
   *  this is a duty-cycle phase warp, identity at PW=64.
   *  UNFITTED for everything but SAW: the warp shape is a guess. */
  warp(p) {
    const w = this.pw;                     // 0.5 = PW 64 (50:50, per the guide)
    if (w <= 0.001 || w >= 0.999 || Math.abs(w - 0.5) < 1e-4) return p;
    return p < w ? 0.5 * (p / w) : 0.5 + 0.5 * ((p - w) / (1 - w));
  }

  /** SAW under PW, MEASURED 2026-09-24 against Zenology 2.0.9 ("MEAS SAW",
   *  PW 0..127, renders/mx-pw): PW 64 is a plain saw, and moving PW either way
   *  turns it into a variable-slope triangle whose short edge takes
   *  |PW-64|/127 of the cycle, capped at a pure triangle (1/2). So PW 0 is a
   *  pure triangle while a stored PW 127 stops just short of one (harmonic 2
   *  at -45 dB) - but a matrix route pushing PW past 127 does reach it, so the
   *  cap is on the shape, not on PW. The harmonic nulls land where that shape
   *  puts them (PW 32: k = 4, 8, 12 at -41..-62 dB) and the level stays
   *  constant, as it does for a fixed-peak triangle.
   *  Aliasing: polyBLAMP on both kinks; it helps little once the short edge is
   *  under ~2 samples (very high notes near PW 64). */
  sawMorph(p, dt) {
    // Zenology's saw FALLS (renders/osc: harmonic phases 0, +pi/2, pi, ...), so
    // the rising construction below is negated - what matters wherever saws
    // combine (SuperSAW, sync, ring, layered partials)
    const r = Math.min(0.5, Math.abs(this.pw - 0.5));     // |PW-64|/127
    if (r < dt) return -(2 * p - 1 - blep(p, dt));       // edge shorter than a sample
    const q = 1 - r;                                      // where the peak sits
    const v = p < q ? -1 + (2 * p) / q : 1 - (2 * (p - q)) / r;
    const k = (2 / r + 2 / q) * dt;                       // slope change per sample
    return -(v + k * blamp(p, dt) - k * blamp((p - q + 1) % 1, dt));
  }

  shape(p, dt) {
    if (this.table) {
      // captured waveform; PW warps its phase - UNFITTED: Zenology's shapes do
      // follow PW (half a PW step gives SIN a 2nd harmonic, +29 dB), and the
      // warp tracks SIN, TRI2 and RAMP roughly; JUNO barely moves in Zenology
      // (0.4 dB) and the warp over-reacts (2 dB), so JUNO is not warped
      const x = (this.form === "JUNO" ? p : this.warp(p)) * WT_SIZE, i = x | 0, f = x - i;
      return this.table[i] + (this.table[i + 1] - this.table[i]) * f;
    }
    if (this.form === "SQR") {
      let v = p < this.pw ? 1 : -1;
      v += blep(p, dt);
      v -= blep((p - this.pw + 1) % 1, dt);
      return v * (WAVES.sqr ?? 0.5);
    }
    if (this.form === "SAW") return this.sawMorph(p, dt);
    // SQR carries its own duty cycle; everything else is warped by PW.
    if (this.form !== "SQR" && this.form !== "JUNO") p = this.warp(p);
    switch (this.form) {
      case "RAMP":
        return -(2 * p - 1 - blep(p, dt));
      case "SQR": {
        let v = p < this.pw ? 1 : -1;
        v += blep(p, dt);
        v -= blep((p - this.pw + 1) % 1, dt);
        return v;
      }
      case "TRI": {
        // integrate a square for a naturally band-limited triangle
        let s = p < 0.5 ? 1 : -1;
        s += blep(p, dt) - blep((p + 0.5) % 1, dt);
        this._triState = (this._triState || 0) * 0.999 + s * dt * 4;
        return this._triState;
      }
      case "TRI2": return 2 * Math.abs(2 * p - 1) - 1;
      case "TRI3": {
        const t = 2 * Math.abs(2 * p - 1) - 1;
        return Math.sign(t) * Math.pow(Math.abs(t), 0.6);
      }
      case "SIN": return Math.sin(TAU * p);
      // ZEN-Core's Noise oscillator; Zenology's is white to 0.3 dB (renders/noise-open)
      case "NOISE": return Math.random() * 2 - 1;
      case "SIN2": {
        const s = Math.sin(TAU * p);
        return Math.sign(s) * Math.pow(Math.abs(s), 0.7);
      }
      case "JUNO": {
        // modulated sawtooth: saw plus a pulse, the classic Juno stack
        const saw = 2 * p - 1 - blep(p, dt);
        const sq = (p < this.pw ? 1 : -1) + blep(p, dt)
                 - blep((p - this.pw + 1) % 1, dt);
        return 0.6 * saw + 0.4 * sq;
      }
      default: return 2 * p - 1 - blep(p, dt);
    }
  }
}

/* -------------------------------------------------------------------------
 * Envelope - Roland's 4-time / 5-level shape
 * ---------------------------------------------------------------------- */

/** Envelope tables, MEASURED 2026-09-26 against Zenology 2.0.9 with a sine and
 *  the filter open (renders/aenv, renders/adsr; written by fit_env.py).
 *  time: the shared segment-time table (decay, release, and every falling or
 *  middle segment) - 2.048 ms per step up to ~384, then ~doubling per 128 steps,
 *  30 s at 1023. attack: the attack-time table (a separate curve: ~2 ms at 0).
 *  b: ADSR-off level law, amplitude = (2^(L/b) - 1) / (2^(1023/b) - 1).
 *  c: ADSR-off attack curve. adsr: ADSR-on attack curve and times, and the RC
 *  decay/release - tau = distance x T / x, aimed delta below the target. */
export const ENV = /*ENV_TABLES*/{"b": 125.601, "c": 0.9475, "attack": [[0, 0.0019], [128, 0.21456], [256, 0.43052], [384, 0.64649], [512, 1.38822], [640, 2.92513], [768, 6.06244], [896, 12.46662], [1023, 24.92909]], "time": [[0, 0.003], [128, 0.26379], [256, 0.51833], [384, 0.77401], [512, 1.64531], [640, 3.46646], [704, 4.99429], [768, 7.27959], [832, 10.28916], [896, 14.74058], [1023, 30.02187]], "adsr": {"c": 1.9005, "attack": [[0, 0.0019], [128, 0.2128], [256, 0.42783], [384, 0.64295], [512, 1.38176], [640, 2.91251], [768, 6.03742], [896, 12.41615], [1023, 25.02098]], "x": 4.5598, "delta": 0.01112}, "release0": 0.013, "pdepth": [[0, 0.0], [1, 0.106], [3, 0.302], [6, 0.752], [9, 1.508], [12, 2.244], [18, 3.746], [25, 5.497], [31, 7.001], [37, 8.499], [44, 10.253], [50, 11.747], [56, 17.002], [60, 20.998], [63, 24.001], [64, 24.499], [66, 26.001], [70, 29.998], [75, 35.0], [82, 42.0], [88, 48.001], [94, 54.0], [97, 57.001], [100, 60.0]]}/*END_ENV_TABLES*/;

/** Segment time for a 0..1023 setting: linear up to 384, exponential above. */
function envSeconds(table, v) {
  if (v <= 384) return interp(table, v, false);
  return interp(table, v, true);
}

/** ADSR-off amplitude of level L (0..1023) and its inverse. */
const levelAmp = (L) => (Math.pow(2, L / ENV.b) - 1) / (Math.pow(2, 1023 / ENV.b) - 1);
const ampLevel = (a) => ENV.b * Math.log2(1 + Math.max(0, a) * (Math.pow(2, 1023 / ENV.b) - 1));

/** Attack curve: fraction of the way at s = t / T (fast start, 1 at s = 1). */
const attackCurve = (s, c) => (1 - Math.exp(-c * s)) / (1 - Math.exp(-c));

/** Roland's 4-time envelope, MEASURED 2026-09-26 (renders/aenv, adsr, penv).
 *  ADSR off:
 *   - amp: T1 is the attack curve toward L1's amplitude on its own table
 *     (ENV.attack); T2, T3, T4 ramp the LEVEL linearly over the full time of
 *     the shared table, whatever the distance; amplitude is levelAmp(L).
 *   - pitch (and filter, assumed the same - not measured separately): every
 *     segment, T1 included, is a straight line over the shared table.
 *  ADSR on (the guide: T2, L1, L2 ignored) - one model for every envelope, in
 *  levels normalised to its top (amp and filter 1023, pitch 511): L0 is
 *  ignored (starts at 0); the amp ADSR attack curve to the top; an RC decay to
 *  L3 whose time constant scales with the distance; an RC release to 0 with a
 *  fixed one. Amp levels are then linear amplitude.
 *  tick() returns amplitude 0..1 for amp envelopes, level / 1023 otherwise. */
export class Env {
  constructor(sampleRate, stages, { amp = false, adsr = false, top = 1023 } = {}) {
    this.sr = sampleRate;
    this.amp = amp;
    this.adsr = adsr;
    this.top = top;
    const L = (k, d) => (stages[k] == null ? d : raw(stages[k], d));
    const hasEnv = !!(ENV.time && ENV.attack);
    const T = (k, table) => Math.max(1e-4, hasEnv ? envSeconds(table, raw(stages[k], 0))
                                                  : SCALE.envTime(raw(stages[k], 0)));
    // At 0, amp segments keep a measured minimum (release ~13 ms, middle
    // ~3 ms); pitch/filter segments at 0 are instant (renders/penv).
    const zero = (tab, v) => hasEnv ? [[0, v]].concat(tab.slice(1)) : tab;
    const time = amp ? ENV.time : zero(ENV.time, 1e-4);
    const relTable = amp && ENV.release0 != null ? zero(ENV.time, ENV.release0) : time;
    const t1Table = adsr ? ENV.adsr?.attack ?? ENV.attack : amp ? ENV.attack : time;
    this.t = [T("T1", t1Table), adsr ? 0 : T("T2", time), T("T3", time), T("T4", relTable)];
    // levels in the envelope's own units (0..1023 amp/filter, -511..511 pitch)
    this.L = adsr
      ? [0, top, top, L("L3", amp ? 1023 : 0), 0]
      : amp ? [0, L("L1", 1023), L("L2", 1023), L("L3", 1023), 0]
            : [L("L0", 0), L("L1", 0), L("L2", 0), L("L3", 0), L("L4", 0)];
    this.stage = 0;
    this.time = 0;
    this.level = this.L[0];             // current level, envelope units
    this.value = this.out(this.level);
    this.released = false;
  }

  /** Output for a level: amplitude for amp envelopes, level / 1023 otherwise. */
  out(L) {
    if (!this.amp) return L / 1023;
    return this.adsr || !ENV.b ? L / 1023 : levelAmp(L);
  }

  noteOn() { this.stage = 0; this.time = 0; this.released = false; this.from = this.level; }
  noteOff() { this.stage = 3; this.time = 0; this.released = true; this.from = this.level; }

  get done() { return this.released && this.stage > 3; }

  tick() {
    if (this.stage > 3) return this.value;
    const st = this.stage, dur = this.t[st];
    this.time += 1 / this.sr;
    const s = dur > 0 ? Math.min(1, this.time / dur) : 1;
    let finished = s >= 1;
    const to = this.L[st + 1];
    if (st === 0 && (this.amp || this.adsr)) {
      // attack curve (amp; and every envelope in ADSR mode)
      const c = this.adsr ? ENV.adsr?.c ?? 1.9 : ENV.c ?? 0.95;
      if (this.amp && !this.adsr) {
        // ADSR-off amp: the curve runs in amplitude
        const a0 = this.out(this.from), a1 = this.out(to);
        const a = a0 + (a1 - a0) * attackCurve(s, c);
        this.level = ampLevel(a);
        this.value = a;
        return this.advance(finished);
      }
      this.level = this.from + (to - this.from) * attackCurve(s, c);
    } else if (this.adsr && (st === 2 || st === 3)) {
      // RC toward the target in normalised units; decay's time constant scales
      // with the distance, release's does not
      const n0 = this.from / this.top, n1 = to / this.top;
      const dist = Math.abs(n0 - n1), dir = n1 < n0 ? -1 : 1;
      const scale = st === 2 ? Math.max(1e-6, dist) : 1;
      const tau = scale * this.t[st] / (ENV.adsr?.x ?? 4.6);
      const d = (ENV.adsr?.delta ?? 0.01) * scale;
      const aim = n1 + dir * d;                      // just past the target
      const n = aim + (n0 - aim) * Math.exp(-this.time / tau);
      const past = dir < 0 ? n <= n1 : n >= n1;
      this.level = (past ? n1 : n) * this.top;
      finished = past;
    } else {
      // straight line in level over the full segment time
      this.level = this.from + (to - this.from) * s;
    }
    this.value = this.out(this.level);
    return this.advance(finished);
  }

  advance(finished) {
    if (finished) {
      if (this.stage === 2 && !this.released) return this.value;   // sustain
      this.stage += 1;
      this.time = 0;
      this.from = this.level;
    }
    return this.value;
  }
}

/* -------------------------------------------------------------------------
 * Filter - the ZEN-Core VA lowpass
 * ---------------------------------------------------------------------- */

/** Zenology's VA filter, MEASURED 2026-09-25 (Zenology 2.0.9) with a white-noise
 *  probe - the Noise oscillator is white to 0.3 dB - through every VCF_TYPE x
 *  FILTER_SLOPE x RESO x CUTOFF (renders/fs, renders/fd):
 *
 *  This is the VCF, used when the partial's filter mode (PCMS FILTER_TYPE) is
 *  VCF. The TVF - the other mode - is TvfFilter below.
 *  - In VCF mode it is always a lowpass: the TVF type (PCMT FILTER_TYPE, OFF/
 *    LPF/BPF/HPF/PKG/LPF2/LPF3) gave byte-identical audio on VCF1 and JP, as
 *    the Parameter Guide says ("If Filter Type is set to VCF, this will be LPF").
 *  - Every model is the same structure: four identical one-pole stages with
 *    resonance fed back from stage 4, and FILTER_SLOPE choosing which stage is
 *    heard (-12/-18/-24 = after stage 2/3/4). Evidence: the passband drop with
 *    resonance is identical at every slope, and the peak sits at the stage
 *    cutoff for all of them.
 *  - It is a bilinear (zero-delay-feedback) ladder: that digital response fits
 *    Zenology to 0.01-0.05 dB up to 22 kHz; an analog one misses by 4+ dB above
 *    CUTOFF 768.
 *  - No passband compensation: RESO costs level (-13.5 dB at RESO 900), as in
 *    an analog ladder, i.e. 1 / (1 + k).
 *
 *  The models differ only in their cutoff law and resonance curve, tabulated
 *  in VCF_MODELS from webui/compare/fit_vcf.py. Near self-oscillation the
 *  ladder saturates: in the feedback (sat) and at its input (insat, per model),
 *  with MG's top k refitted through that nonlinearity (VCF_EXTRA.knl).
 *
 *  Validation vs Zenology, 2026-09-26 (webui/compare/validate_filters.py):
 *  noise, 108 settings: 0.55-0.60 dB mean (run-to-run spread ~0.05), worst
 *  ~3 dB on P5 at RESO 900; saw, filter only: RESO 0 0.32 dB, RESO 800 1.24 dB.
 *  RESO 1023 on a saw is 1-5 dB louder than Zenology's; a ring far below the
 *  note (CUTOFF 256, strong resonance) is 7-11 dB off - set by the note-on
 *  transient. */
export class Filter {
  constructor(sampleRate) { this.sr = sampleRate; this.s = [0, 0, 0, 0]; }

  /** hz: stage cutoff; k: feedback (4 = self-oscillation); poles: 2|3|4;
   *  sat: the feedback's saturation level; insat: the ladder input's (0 = none).
   *  Both per model, VCF_EXTRA. */
  process(x, hz, k, poles = 4, sat = 1, insat = 0) {
    const s = this.s;
    const g = Math.tan(Math.PI * Math.min(hz, this.sr * 0.49) / this.sr);
    const G = g / (1 + g);
    const b = 1 / (1 + g);
    // Solve the feedback loop for this sample (no unit delay):
    // y4 = G^4 u + b (G^3 s0 + G^2 s1 + G s2 + s3), u = x - k y4
    const sigma = b * (G * (G * (G * s[0] + s[1]) + s[2]) + s[3]);
    const G4 = G * G * G * G;
    // Saturate only what is fed back: at RESO 0 the filter is then exactly
    // linear, as Zenology's is (its reso-0 harmonics fit a linear ladder to
    // 0.1 dB at full level), while self-oscillation stays bounded.
    const y4 = (G4 * x + sigma) / (1 + k * G4);
    let u = x - k * sat * Math.tanh(y4 / sat);
    // Input saturation: fitted per model on Zenology's saw at RESO 0/800/1023
    // (renders/ab, renders/selfosc); it tames strong resonance without
    // touching RESO 0, which stays within 0.1-0.2 dB. MG fits best without it.
    const L = K.vcfInSat ?? insat;
    if (L) u = L * Math.tanh(u / L);
    let out = u;
    for (let i = 0; i < 4; i++) {                    // all four run: stage 4 feeds back
      const w = (u - s[i]) * G;
      const y = w + s[i];
      s[i] = y + w;
      u = y;
      if (i === poles - 1) out = y;
    }
    return out;
  }
}

